    /// Parse verbatim_text
    fn parse_verbatim_text<F>(&mut self, on_event: &mut F)
    where
        F: FnMut(Event<'a>),
    {
                    self.mark();
        #[derive(Clone, Copy)]
        enum State { Main, Vpipe, Vbang, Vsemi, Vbs, VbsPipe, VbsBang, VbsSemi, Vafter,  }
        let mut state = State::Main;
        loop {
            match state {
                State::Main => {
                    match self.scan_to5(b'\n', b'|', b'!', b';', b'\\') {
                        Some(b'\n') => {
                    self.set_term(0);
                    on_event(Event::Text { content: self.term(), span: self.span_from_mark() });
                    return;
                        }
                        Some(b'|') => {
                    self.advance();
                    state = State::Vpipe;
                    continue;
                        }
                        Some(b'!') => {
                    self.advance();
                    state = State::Vbang;
                    continue;
                        }
                        Some(b';') => {
                    self.advance();
                    state = State::Vsemi;
                    continue;
                        }
                        Some(b'\\') => {
                    self.advance();
                    state = State::Vbs;
                    continue;
                        }
                        None => {
                    self.set_term(0);
                    on_event(Event::Text { content: self.term(), span: self.span_from_mark() });
                    return;
                        }
                        _ => unreachable!("scan_to only returns target chars"),
                    }
                }
                State::Vpipe => {
                    if self.eof() {
                        on_event(Event::Error { code: ParseErrorCode::Unclosed, span: self.span() });
                        return;
                    }
                    match self.peek() {
                        Some(b'{') => {
                    self.set_term(-1);
                    on_event(Event::Text { content: self.term(), span: self.span_from_mark() });
                    self.advance();
                    self.parse_embedded(on_event);
                    state = State::Vafter;
                    continue;
                        }
                        _ => {
                    state = State::Main;
                    continue;
                        }
                    }
                }
                State::Vbang => {
                    if self.eof() {
                        on_event(Event::Error { code: ParseErrorCode::Unclosed, span: self.span() });
                        return;
                    }
                    match self.peek() {
                        Some(b'{') => {
                    self.set_term(-1);
                    on_event(Event::Text { content: self.term(), span: self.span_from_mark() });
                    self.advance();
                    self.parse_sameline_directive(on_event);
                    state = State::Vafter;
                    continue;
                        }
                        _ => {
                    state = State::Main;
                    continue;
                        }
                    }
                }
                State::Vsemi => {
                    if self.eof() {
                        on_event(Event::Error { code: ParseErrorCode::Unclosed, span: self.span() });
                        return;
                    }
                    match self.peek() {
                        Some(b'{') => {
                    self.set_term(-1);
                    on_event(Event::Text { content: self.term(), span: self.span_from_mark() });
                    self.advance();
                    self.parse_brace_comment(on_event);
                    state = State::Vafter;
                    continue;
                        }
                        _ => {
                    state = State::Main;
                    continue;
                        }
                    }
                }
                State::Vbs => {
                    if self.eof() {
                        on_event(Event::Error { code: ParseErrorCode::Unclosed, span: self.span() });
                        return;
                    }
                    match self.peek() {
                        Some(b'|') => {
                    self.advance();
                    state = State::VbsPipe;
                    continue;
                        }
                        Some(b'!') => {
                    self.advance();
                    state = State::VbsBang;
                    continue;
                        }
                        Some(b';') => {
                    self.advance();
                    state = State::VbsSemi;
                    continue;
                        }
                        _ => {
                    state = State::Main;
                    continue;
                        }
                    }
                }
                State::VbsPipe => {
                    if self.eof() {
                        on_event(Event::Error { code: ParseErrorCode::Unclosed, span: self.span() });
                        return;
                    }
                    match self.peek() {
                        Some(b'{') => {
                    self.set_term(-2);
                    on_event(Event::Text { content: self.term(), span: self.span_from_mark() });
                    self.mark();
                    self.prepend_bytes(b"|");
                    state = State::Main;
                    continue;
                        }
                        _ => {
                    state = State::Main;
                    continue;
                        }
                    }
                }
                State::VbsBang => {
                    if self.eof() {
                        on_event(Event::Error { code: ParseErrorCode::Unclosed, span: self.span() });
                        return;
                    }
                    match self.peek() {
                        Some(b'{') => {
                    self.set_term(-2);
                    on_event(Event::Text { content: self.term(), span: self.span_from_mark() });
                    self.mark();
                    self.prepend_bytes(b"!");
                    state = State::Main;
                    continue;
                        }
                        _ => {
                    state = State::Main;
                    continue;
                        }
                    }
                }
                State::VbsSemi => {
                    if self.eof() {
                        on_event(Event::Error { code: ParseErrorCode::Unclosed, span: self.span() });
                        return;
                    }
                    match self.peek() {
                        Some(b'{') => {
                    self.set_term(-2);
                    on_event(Event::Text { content: self.term(), span: self.span_from_mark() });
                    self.mark();
                    self.prepend_bytes(b";");
                    state = State::Main;
                    continue;
                        }
                        _ => {
                    state = State::Main;
                    continue;
                        }
                    }
                }
                State::Vafter => {
                    if self.eof() {
                    return;
                    }
                    match self.peek() {
                        Some(b'\n') => {
                    return;
                        }
                        _ => {
                    self.mark();
                    state = State::Main;
                    continue;
                        }
                    }
                }
            }
        }
    }

    /// Parse prose
    fn parse_prose<F>(&mut self, line_col: i32, parent_col: i32, prepend: &'static [u8], on_event: &mut F)
    where
        F: FnMut(Event<'a>),
    {
                    if parent_col >= 0 && line_col <= parent_col {
                    return;
                    }
        loop {
                    self.parse_text(line_col, parent_col, prepend, on_event);
                    return;
        }
    }

    /// Parse prose_backticks
    fn parse_prose_backticks<F>(&mut self, line_col: i32, parent_col: i32, on_event: &mut F)
    where
        F: FnMut(Event<'a>),
    {
                    if parent_col >= 0 && line_col <= parent_col {
                    return;
                    }
        loop {
                    self.parse_text_backticks(line_col, parent_col, on_event);
                    return;
        }
    }

    /// Parse text_backticks
    fn parse_text_backticks<F>(&mut self, line_col: i32, parent_col: i32, on_event: &mut F)
    where
        F: FnMut(Event<'a>),
    {
        #[derive(Clone, Copy)]
        enum State { Entry, Main, CheckPipe, CheckSemi, CheckBang, CheckBs, CheckBsPipe, CheckBsBang, CheckBsSemi, AfterInline,  }
        let mut state = State::Entry;
        loop {
            match state {
                State::Entry => {
                    self.mark();
                    self.prepend_bytes(b"`");
                    self.prepend_bytes(b"`");
                    state = State::Main;
                    continue;
                }
                State::Main => {
                    match self.scan_to5(b'\n', b'|', b';', b'!', b'\\') {
                        Some(b'\n') => {
                    self.set_term(0);
                    on_event(Event::Text { content: self.term(), span: self.span_from_mark() });
                    return;
                        }
                        Some(b'|') => {
                    self.advance();
                    state = State::CheckPipe;
                    continue;
                        }
                        Some(b';') => {
                    self.advance();
                    state = State::CheckSemi;
                    continue;
                        }
                        Some(b'!') => {
                    self.advance();
                    state = State::CheckBang;
                    continue;
                        }
                        Some(b'\\') => {
                    self.advance();
                    state = State::CheckBs;
                    continue;
                        }
                        None => {
                    self.set_term(0);
                    on_event(Event::Text { content: self.term(), span: self.span_from_mark() });
                    return;
                        }
                        _ => unreachable!("scan_to only returns target chars"),
                    }
                }
                State::CheckPipe => {
                    if self.eof() {
                    self.set_term(0);
                    on_event(Event::Text { content: self.term(), span: self.span_from_mark() });
                    return;
                    }
                    match self.peek() {
                        Some(b'{') => {
                    self.set_term(-1);
                    on_event(Event::Text { content: self.term(), span: self.span_from_mark() });
                    self.advance();
                    self.parse_embedded(on_event);
                    state = State::AfterInline;
                    continue;
                        }
                        _ => {
                    state = State::Main;
                    continue;
                        }
                    }
                }
                State::CheckSemi => {
                    if self.eof() {
                    self.set_term(0);
                    on_event(Event::Text { content: self.term(), span: self.span_from_mark() });
                    return;
                    }
                    match self.peek() {
                        Some(b'{') => {
                    self.set_term(-1);
                    on_event(Event::Text { content: self.term(), span: self.span_from_mark() });
                    self.advance();
                    self.parse_brace_comment(on_event);
                    state = State::AfterInline;
                    continue;
                        }
                        _ => {
                    state = State::Main;
                    continue;
                        }
                    }
                }
                State::CheckBang => {
                    if self.eof() {
                    self.set_term(0);
                    on_event(Event::Text { content: self.term(), span: self.span_from_mark() });
                    return;
                    }
                    match self.peek() {
                        Some(b'{') => {
                    self.set_term(-1);
                    on_event(Event::Text { content: self.term(), span: self.span_from_mark() });
                    self.advance();
                    self.parse_sameline_directive(on_event);
                    state = State::AfterInline;
                    continue;
                        }
                        _ => {
                    state = State::Main;
                    continue;
                        }
                    }
                }
                State::CheckBs => {
                    if self.eof() {
                        on_event(Event::Error { code: ParseErrorCode::Unclosed, span: self.span() });
                        return;
                    }
                    match self.peek() {
                        Some(b'|') => {
                    self.advance();
                    state = State::CheckBsPipe;
                    continue;
                        }
                        Some(b'!') => {
                    self.advance();
                    state = State::CheckBsBang;
                    continue;
                        }
                        Some(b';') => {
                    self.advance();
                    state = State::CheckBsSemi;
                    continue;
                        }
                        _ => {
                    state = State::Main;
                    continue;
                        }
                    }
                }
                State::CheckBsPipe => {
                    if self.eof() {
                        on_event(Event::Error { code: ParseErrorCode::Unclosed, span: self.span() });
                        return;
                    }
                    match self.peek() {
                        Some(b'{') => {
                    self.set_term(-2);
                    on_event(Event::Text { content: self.term(), span: self.span_from_mark() });
                    self.mark();
                    self.prepend_bytes(b"|");
                    state = State::Main;
                    continue;
                        }
                        _ => {
                    state = State::Main;
                    continue;
                        }
                    }
                }
                State::CheckBsBang => {
                    if self.eof() {
                        on_event(Event::Error { code: ParseErrorCode::Unclosed, span: self.span() });
                        return;
                    }
                    match self.peek() {
                        Some(b'{') => {
                    self.set_term(-2);
                    on_event(Event::Text { content: self.term(), span: self.span_from_mark() });
                    self.mark();
                    self.prepend_bytes(b"!");
                    state = State::Main;
                    continue;
                        }
                        _ => {
                    state = State::Main;
                    continue;
                        }
                    }
                }
                State::CheckBsSemi => {
                    if self.eof() {
                        on_event(Event::Error { code: ParseErrorCode::Unclosed, span: self.span() });
                        return;
                    }
                    match self.peek() {
                        Some(b'{') => {
                    self.set_term(-2);
                    on_event(Event::Text { content: self.term(), span: self.span_from_mark() });
                    self.mark();
                    self.prepend_bytes(b";");
                    state = State::Main;
                    continue;
                        }
                        _ => {
                    state = State::Main;
                    continue;
                        }
                    }
                }
                State::AfterInline => {
                    if self.eof() {
                    return;
                    }
                    match self.peek() {
                        Some(b'\n') => {
                    return;
                        }
                        _ => {
                    self.mark();
                    state = State::Main;
                    continue;
                        }
                    }
                }
            }
        }
    }

